using namespace std;

int binarySearch(vector<string> lista, string item) {
    if (lista.empty()) {
        return -1; // Возвращаем -1, если список пуст
    }

    if (lista[0] == item) {
        return 0;
    }

    int low = -1;
    int high = lista.size() - 1;

